//! Helpers for Python-to-Rust compatibility tests.
//!
//! Fixtures live in `tests/fixtures/` and are generated by the Python v3.0
//! build (history.db, JSON journals, SFOVAULT v1 files, config JSON).

use std::path::PathBuf;

/// Absolute path to the fixtures directory.
pub fn fixtures_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests")
        .join("fixtures")
}
